using System;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;

public static class ConfigurePlayerLocomotion
{
    private static AnimationClip LoadClip(string path)
    {
        foreach (var asset in AssetDatabase.LoadAllAssetsAtPath(path))
        {
            if (asset is AnimationClip clip && !clip.name.StartsWith("__preview__")) return clip;
        }
        throw new Exception("Animation clip not found: " + path);
    }

    public static void Execute(GameObject player)
    {
        var controller = AssetDatabase.LoadAssetAtPath<AnimatorController>("Assets/_Project/Animations/PlayerLocomotion.controller");
        var idle = LoadClip("Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Base/Stances/A_POLY_IDL_Base_Masc.fbx");
        var walk = LoadClip("Assets/Synty/AnimationBaseLocomotion/Animations/Polygon/Masculine/Locomotion/Walk/A_Walk_F_Masc.fbx");
        var run = LoadClip("Assets/Synty/AnimationBaseLocomotion/Animations/Polygon/Masculine/Locomotion/Run/A_Run_F_Masc.fbx");
        var stateMachine = controller.layers[0].stateMachine;
        foreach (var childState in stateMachine.states) stateMachine.RemoveState(childState.state);
        var hasSpeed = false;
        foreach (var parameter in controller.parameters) if (parameter.name == "Speed") hasSpeed = true;
        if (!hasSpeed) controller.AddParameter("Speed", AnimatorControllerParameterType.Float);
        var idleState = stateMachine.AddState("Idle");
        var walkState = stateMachine.AddState("Walk");
        var runState = stateMachine.AddState("Run");
        idleState.motion = idle;
        walkState.motion = walk;
        runState.motion = run;
        stateMachine.defaultState = idleState;
        var idleToWalk = idleState.AddTransition(walkState);
        idleToWalk.hasExitTime = false; idleToWalk.duration = 0.12f; idleToWalk.AddCondition(AnimatorConditionMode.Greater, 0.1f, "Speed");
        var walkToIdle = walkState.AddTransition(idleState);
        walkToIdle.hasExitTime = false; walkToIdle.duration = 0.12f; walkToIdle.AddCondition(AnimatorConditionMode.Less, 0.1f, "Speed");
        var walkToRun = walkState.AddTransition(runState);
        walkToRun.hasExitTime = false; walkToRun.duration = 0.12f; walkToRun.AddCondition(AnimatorConditionMode.Greater, 0.75f, "Speed");
        var runToWalk = runState.AddTransition(walkState);
        runToWalk.hasExitTime = false; runToWalk.duration = 0.12f; runToWalk.AddCondition(AnimatorConditionMode.Less, 0.75f, "Speed");
        var animator = player.GetComponent<Animator>();
        animator.runtimeAnimatorController = controller;
        animator.applyRootMotion = false;
        animator.Rebind();
        EditorUtility.SetDirty(controller);
        EditorUtility.SetDirty(player);
        AssetDatabase.SaveAssets();
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(player.scene);
        Debug.Log("[FarmAnimation] Locomotion configured: Idle, Walk, Run.");
    }
}
